select set_config('test.aw',public.get_project_detail(current_setting('test.ap')::uuid)->'parts'->0->>'workItemId',true);
select set_config('test.part',public.apply_project_part_command(current_setting('test.ap')::uuid,gen_random_uuid(),0,'{"type":"create","name":"소매"}')::text,true);
reset role;
