select pg_temp.seed_session((current_setting('test.part')::jsonb->>'workItemId')::uuid,'eeeeeeee-1000-4000-8000-000000000002','2026-10-22T00:00Z',null,null,'2026-10-22T00:00Z');
set local role authenticated;
select is(public.get_work_time_adjustments('eeeeeeee-1000-4000-8000-000000000001')->>'effectiveMs','4500000','original effective duration');
