select is(public.get_work_time_statistics('UTC',null,current_setting('test.aw')::uuid)->'recent'->0->>'accumulatedMs','4500000','recent original time retained');
select is(public.adjust_work_session_time(gen_random_uuid(),'eeeeeeee-1000-4000-8000-000000000001',0,1,'stale')->>'status','conflict','concurrent/stale revision conflict');
