select throws_ok('select public.adjust_work_session_time(gen_random_uuid(),''eeeeeeee-1000-4000-8000-000000000001'',2,9007199254740992,'''')','22023',null,'unsafe correction rejected');
select throws_ok('select public.adjust_work_session_time(gen_random_uuid(),''eeeeeeee-1000-4000-8000-000000000001'',2,1,repeat(''x'',1001))','22023',null,'long reason rejected');
select is(public.adjust_work_session_time(gen_random_uuid(),'eeeeeeee-1000-4000-8000-000000000001',2,10,'밀리초 보존')->>'status','applied','multiple corrections retained');
select is((public.get_work_time_statistics('UTC',null,current_setting('test.aw')::uuid,0,'2026-10-20')->'works'->0->>'todaySavedMs')::bigint+(public.get_work_time_statistics('UTC',null,current_setting('test.aw')::uuid,0,'2026-10-21')->'works'->0->>'todaySavedMs')::bigint,10::bigint,'daily sum conserves corrected milliseconds');
