select is(public.get_work_time_statistics('UTC',null,current_setting('test.aw')::uuid)->'works'->0->>'savedMs','10','deleted project corrected totals preserved');
select is(public.adjust_work_session_time('eeeeeeee-2000-4000-8000-000000000001','eeeeeeee-1000-4000-8000-000000000001',0,6000000,'기록 정정')->>'status','duplicate','applied receipt survives deletion');
select is(public.restore_project(current_setting('test.ap')::uuid,gen_random_uuid(),2)->>'status','restored','project restored');
select is(public.update_project(current_setting('test.ap')::uuid,3,'정정 프로젝트',null,'paused')->>'result','updated','paused project');
select is(public.adjust_work_session_time(gen_random_uuid(),'eeeeeeee-1000-4000-8000-000000000001',3,1000,'완료 기록 관리')->>'status','applied','paused project ended session may be corrected');
select is(public.update_project(current_setting('test.ap')::uuid,4,'정정 프로젝트',null,'active')->>'result','updated','project resumed');
select is(public.adjust_work_session_time(gen_random_uuid(),'eeeeeeee-1000-4000-8000-000000000002',0,1000,'원본 0')->>'status','applied','zero-original correction');
select is(public.get_work_time_statistics('UTC',null,(current_setting('test.part')::jsonb->>'workItemId')::uuid,0,'2026-10-21')->'works'->0->>'todaySavedMs','0','zero original does not assign earlier date');
select is(public.get_work_time_statistics('UTC',null,(current_setting('test.part')::jsonb->>'workItemId')::uuid,0,'2026-10-22')->'works'->0->>'todaySavedMs','1000','zero original assigned to end date');
select is(public.apply_project_part_command(current_setting('test.ap')::uuid,gen_random_uuid(),5,jsonb_build_object('type','delete','partId',current_setting('test.part')::jsonb->>'partId'))->>'status','applied','corrected part soft deleted');
select throws_ok('select public.adjust_work_session_time(gen_random_uuid(),''eeeeeeee-1000-4000-8000-000000000002'',1,1,'''')','22023',null,'deleted part correction blocked');
select is(public.restore_project_part(current_setting('test.ap')::uuid,(current_setting('test.part')::jsonb->>'partId')::uuid,gen_random_uuid(),6)->>'status','restored','corrected part restored');
select is(public.get_work_time_adjustments('eeeeeeee-1000-4000-8000-000000000002')->>'effectiveMs','1000','part correction retained after recovery');
reset role;
select pg_temp.seed_session(current_setting('test.aw')::uuid,'eeeeeeee-1000-4000-8000-000000000003',date_trunc('milliseconds',clock_timestamp()),null,null,null);
set local role authenticated;
